// LRUCache.hpp
#ifndef LRU_CACHE_HPP
#define LRU_CACHE_HPP

#include <cstddef>
#include <optional>
#include <unordered_map>
#include <list>
#include <mutex>

template <typename K, typename V>
class LRUCache {
public:
    explicit LRUCache(std::size_t capacity)
        : capacity_(capacity) {}

    std::optional<V> get(const K& key) const {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::nullopt;
        }
        // Move to front to mark as recently used
        cache_.splice(cache_.begin(), cache_, it->second);
        return cache_.front().second;
    }

    void put(const K& key, const V& value) {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = map_.find(key);
        if (it != map_.end()) {
            // Update existing key and mark as recently used
            cache_.erase(it->second);
            cache_.push_front({key, value});
            it->second = cache_.begin();
        } else {
            if (capacity_ == 0) {
                return;
            }
            if (cache_.size() >= capacity_) {
                map_.erase(cache_.back().first);
                cache_.pop_back();
            }
            cache_.push_front({key, value});
            map_[key] = cache_.begin();
        }
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mu_);
        return cache_.size();
    }

private:
    std::size_t capacity_;
    mutable std::mutex mu_;
    std::list<std::pair<K, V>> cache_;
    std::unordered_map<K, std::list<std::pair<K, V>>::iterator> map_;
};

#endif // LRU_CACHE_HPP
